-- @saasreport/cloudflare: podcast provenance triggers, replaced. GENERATED by `kit podcast migrate` from kit.podcast-provenance.v1 and the
-- project's podcast.config.json provenance.origins (cron, cron-retry, catchup, admin, legacy); never hand-edited. Same rule as the first provenance migration:
-- the database validates the whole record on insert and on update (now with the catchup origin and its missed_date).
DROP TRIGGER IF EXISTS podcast_provenance_insert;
DROP TRIGGER IF EXISTS podcast_provenance_update;
CREATE TRIGGER podcast_provenance_insert BEFORE INSERT ON podcast_episodes
WHEN NEW.provenance_json IS NULL OR NOT COALESCE(CASE WHEN json_valid(NEW.provenance_json) AND json_type(NEW.provenance_json) = 'object' THEN (((json_type(NEW.provenance_json, '$') IN ('object')) AND (NOT EXISTS (SELECT 1 FROM json_each(NEW.provenance_json, '$') WHERE key NOT IN ('v', 'origin', 'trigger', 'scheduled_at', 'series', 'ref', 'spec_sha256', 'config_sha256', 'engine', 'created_at', 'note', 'render', 'missed_date'))) AND (((json_type(NEW.provenance_json, '$.v') = 'integer') AND (json_extract(NEW.provenance_json, '$.v') = 1))) AND (((json_extract(NEW.provenance_json, '$.origin') IN ('cron', 'cron-retry', 'catchup', 'admin', 'legacy')))) AND (((json_extract(NEW.provenance_json, '$.trigger') IN ('scheduled', 'admin-api', 'migration')))) AND ((json_type(NEW.provenance_json, '$.scheduled_at') IS NULL OR ((json_type(NEW.provenance_json, '$.scheduled_at') IN ('text')) AND (substr(json_extract(NEW.provenance_json, '$.scheduled_at'), 1, 10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(json_extract(NEW.provenance_json, '$.scheduled_at'), 11, 6) GLOB 'T[0-9][0-9]:[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.scheduled_at')) >= 17)))) AND (((json_type(NEW.provenance_json, '$.series') IN ('text')))) AND (((json_type(NEW.provenance_json, '$.ref') IN ('text', 'null')))) AND (((json_type(NEW.provenance_json, '$.spec_sha256') IN ('text')) AND (length(json_extract(NEW.provenance_json, '$.spec_sha256')) = 64 AND json_extract(NEW.provenance_json, '$.spec_sha256') NOT GLOB '*[^0-9a-f]*'))) AND ((json_type(NEW.provenance_json, '$.config_sha256') IS NULL OR ((json_type(NEW.provenance_json, '$.config_sha256') IN ('text')) AND (length(json_extract(NEW.provenance_json, '$.config_sha256')) = 64 AND json_extract(NEW.provenance_json, '$.config_sha256') NOT GLOB '*[^0-9a-f]*')))) AND ((json_type(NEW.provenance_json, '$.engine') IS NULL OR ((json_type(NEW.provenance_json, '$.engine') IN ('text'))))) AND (((json_type(NEW.provenance_json, '$.created_at') IN ('text')) AND (substr(json_extract(NEW.provenance_json, '$.created_at'), 1, 10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(json_extract(NEW.provenance_json, '$.created_at'), 11, 6) GLOB 'T[0-9][0-9]:[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.created_at')) >= 17))) AND ((json_type(NEW.provenance_json, '$.note') IS NULL OR ((json_type(NEW.provenance_json, '$.note') IN ('text'))))) AND ((json_type(NEW.provenance_json, '$.render') IS NULL OR ((json_type(NEW.provenance_json, '$.render') IN ('object')) AND (NOT EXISTS (SELECT 1 FROM json_each(NEW.provenance_json, '$.render') WHERE key NOT IN ('provider', 'model', 'voices', 'pacing', 'chunks', 'duration_ms', 'longest_pause_ms', 'rendered_at'))) AND ((json_type(NEW.provenance_json, '$.render.provider') IS NULL OR ((json_type(NEW.provenance_json, '$.render.provider') IN ('text'))))) AND ((json_type(NEW.provenance_json, '$.render.model') IS NULL OR ((json_type(NEW.provenance_json, '$.render.model') IN ('text', 'null'))))) AND ((json_type(NEW.provenance_json, '$.render.voices') IS NULL OR ((json_type(NEW.provenance_json, '$.render.voices') IN ('object'))))) AND ((json_type(NEW.provenance_json, '$.render.pacing') IS NULL OR ((json_type(NEW.provenance_json, '$.render.pacing') IN ('object'))))) AND ((json_type(NEW.provenance_json, '$.render.chunks') IS NULL OR ((json_type(NEW.provenance_json, '$.render.chunks') IN ('integer')) AND ((json_extract(NEW.provenance_json, '$.render.chunks') IS NULL OR json_extract(NEW.provenance_json, '$.render.chunks') >= 1))))) AND ((json_type(NEW.provenance_json, '$.render.duration_ms') IS NULL OR ((json_type(NEW.provenance_json, '$.render.duration_ms') IN ('integer')) AND ((json_extract(NEW.provenance_json, '$.render.duration_ms') IS NULL OR json_extract(NEW.provenance_json, '$.render.duration_ms') >= 0))))) AND ((json_type(NEW.provenance_json, '$.render.longest_pause_ms') IS NULL OR ((json_type(NEW.provenance_json, '$.render.longest_pause_ms') IN ('integer', 'null')) AND ((json_extract(NEW.provenance_json, '$.render.longest_pause_ms') IS NULL OR json_extract(NEW.provenance_json, '$.render.longest_pause_ms') >= 0))))) AND ((json_type(NEW.provenance_json, '$.render.rendered_at') IS NULL OR ((json_type(NEW.provenance_json, '$.render.rendered_at') IN ('text')) AND (substr(json_extract(NEW.provenance_json, '$.render.rendered_at'), 1, 10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(json_extract(NEW.provenance_json, '$.render.rendered_at'), 11, 6) GLOB 'T[0-9][0-9]:[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.render.rendered_at')) >= 17))))))) AND ((json_type(NEW.provenance_json, '$.missed_date') IS NULL OR ((json_type(NEW.provenance_json, '$.missed_date') IN ('text')) AND (json_extract(NEW.provenance_json, '$.missed_date') GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.missed_date')) = 10))))) AND ((json_extract(NEW.provenance_json, '$.origin') = 'cron' AND json_extract(NEW.provenance_json, '$.trigger') = 'scheduled' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'cron-retry' AND json_extract(NEW.provenance_json, '$.trigger') = 'scheduled' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'catchup' AND json_extract(NEW.provenance_json, '$.trigger') = 'scheduled' AND json_type(NEW.provenance_json, '$.missed_date') IS NOT NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'admin' AND json_extract(NEW.provenance_json, '$.trigger') = 'admin-api' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'legacy' AND json_extract(NEW.provenance_json, '$.trigger') = 'migration' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL))) ELSE 0 END, 0)   -- NULL (a missing field) is a refusal
BEGIN SELECT RAISE(ABORT, 'podcast episode without a valid pipeline provenance record (t=0 rule)'); END;
CREATE TRIGGER podcast_provenance_update BEFORE UPDATE OF provenance_json ON podcast_episodes
WHEN NEW.provenance_json IS NULL OR NOT COALESCE(CASE WHEN json_valid(NEW.provenance_json) AND json_type(NEW.provenance_json) = 'object' THEN (((json_type(NEW.provenance_json, '$') IN ('object')) AND (NOT EXISTS (SELECT 1 FROM json_each(NEW.provenance_json, '$') WHERE key NOT IN ('v', 'origin', 'trigger', 'scheduled_at', 'series', 'ref', 'spec_sha256', 'config_sha256', 'engine', 'created_at', 'note', 'render', 'missed_date'))) AND (((json_type(NEW.provenance_json, '$.v') = 'integer') AND (json_extract(NEW.provenance_json, '$.v') = 1))) AND (((json_extract(NEW.provenance_json, '$.origin') IN ('cron', 'cron-retry', 'catchup', 'admin', 'legacy')))) AND (((json_extract(NEW.provenance_json, '$.trigger') IN ('scheduled', 'admin-api', 'migration')))) AND ((json_type(NEW.provenance_json, '$.scheduled_at') IS NULL OR ((json_type(NEW.provenance_json, '$.scheduled_at') IN ('text')) AND (substr(json_extract(NEW.provenance_json, '$.scheduled_at'), 1, 10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(json_extract(NEW.provenance_json, '$.scheduled_at'), 11, 6) GLOB 'T[0-9][0-9]:[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.scheduled_at')) >= 17)))) AND (((json_type(NEW.provenance_json, '$.series') IN ('text')))) AND (((json_type(NEW.provenance_json, '$.ref') IN ('text', 'null')))) AND (((json_type(NEW.provenance_json, '$.spec_sha256') IN ('text')) AND (length(json_extract(NEW.provenance_json, '$.spec_sha256')) = 64 AND json_extract(NEW.provenance_json, '$.spec_sha256') NOT GLOB '*[^0-9a-f]*'))) AND ((json_type(NEW.provenance_json, '$.config_sha256') IS NULL OR ((json_type(NEW.provenance_json, '$.config_sha256') IN ('text')) AND (length(json_extract(NEW.provenance_json, '$.config_sha256')) = 64 AND json_extract(NEW.provenance_json, '$.config_sha256') NOT GLOB '*[^0-9a-f]*')))) AND ((json_type(NEW.provenance_json, '$.engine') IS NULL OR ((json_type(NEW.provenance_json, '$.engine') IN ('text'))))) AND (((json_type(NEW.provenance_json, '$.created_at') IN ('text')) AND (substr(json_extract(NEW.provenance_json, '$.created_at'), 1, 10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(json_extract(NEW.provenance_json, '$.created_at'), 11, 6) GLOB 'T[0-9][0-9]:[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.created_at')) >= 17))) AND ((json_type(NEW.provenance_json, '$.note') IS NULL OR ((json_type(NEW.provenance_json, '$.note') IN ('text'))))) AND ((json_type(NEW.provenance_json, '$.render') IS NULL OR ((json_type(NEW.provenance_json, '$.render') IN ('object')) AND (NOT EXISTS (SELECT 1 FROM json_each(NEW.provenance_json, '$.render') WHERE key NOT IN ('provider', 'model', 'voices', 'pacing', 'chunks', 'duration_ms', 'longest_pause_ms', 'rendered_at'))) AND ((json_type(NEW.provenance_json, '$.render.provider') IS NULL OR ((json_type(NEW.provenance_json, '$.render.provider') IN ('text'))))) AND ((json_type(NEW.provenance_json, '$.render.model') IS NULL OR ((json_type(NEW.provenance_json, '$.render.model') IN ('text', 'null'))))) AND ((json_type(NEW.provenance_json, '$.render.voices') IS NULL OR ((json_type(NEW.provenance_json, '$.render.voices') IN ('object'))))) AND ((json_type(NEW.provenance_json, '$.render.pacing') IS NULL OR ((json_type(NEW.provenance_json, '$.render.pacing') IN ('object'))))) AND ((json_type(NEW.provenance_json, '$.render.chunks') IS NULL OR ((json_type(NEW.provenance_json, '$.render.chunks') IN ('integer')) AND ((json_extract(NEW.provenance_json, '$.render.chunks') IS NULL OR json_extract(NEW.provenance_json, '$.render.chunks') >= 1))))) AND ((json_type(NEW.provenance_json, '$.render.duration_ms') IS NULL OR ((json_type(NEW.provenance_json, '$.render.duration_ms') IN ('integer')) AND ((json_extract(NEW.provenance_json, '$.render.duration_ms') IS NULL OR json_extract(NEW.provenance_json, '$.render.duration_ms') >= 0))))) AND ((json_type(NEW.provenance_json, '$.render.longest_pause_ms') IS NULL OR ((json_type(NEW.provenance_json, '$.render.longest_pause_ms') IN ('integer', 'null')) AND ((json_extract(NEW.provenance_json, '$.render.longest_pause_ms') IS NULL OR json_extract(NEW.provenance_json, '$.render.longest_pause_ms') >= 0))))) AND ((json_type(NEW.provenance_json, '$.render.rendered_at') IS NULL OR ((json_type(NEW.provenance_json, '$.render.rendered_at') IN ('text')) AND (substr(json_extract(NEW.provenance_json, '$.render.rendered_at'), 1, 10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(json_extract(NEW.provenance_json, '$.render.rendered_at'), 11, 6) GLOB 'T[0-9][0-9]:[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.render.rendered_at')) >= 17))))))) AND ((json_type(NEW.provenance_json, '$.missed_date') IS NULL OR ((json_type(NEW.provenance_json, '$.missed_date') IN ('text')) AND (json_extract(NEW.provenance_json, '$.missed_date') GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND length(json_extract(NEW.provenance_json, '$.missed_date')) = 10))))) AND ((json_extract(NEW.provenance_json, '$.origin') = 'cron' AND json_extract(NEW.provenance_json, '$.trigger') = 'scheduled' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'cron-retry' AND json_extract(NEW.provenance_json, '$.trigger') = 'scheduled' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'catchup' AND json_extract(NEW.provenance_json, '$.trigger') = 'scheduled' AND json_type(NEW.provenance_json, '$.missed_date') IS NOT NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'admin' AND json_extract(NEW.provenance_json, '$.trigger') = 'admin-api' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL) OR (json_extract(NEW.provenance_json, '$.origin') = 'legacy' AND json_extract(NEW.provenance_json, '$.trigger') = 'migration' AND json_type(NEW.provenance_json, '$.missed_date') IS NULL))) ELSE 0 END, 0)   -- NULL (a missing field) is a refusal
BEGIN SELECT RAISE(ABORT, 'podcast episode without a valid pipeline provenance record (t=0 rule)'); END;
